def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    ion = [(props.get(x.get('element')) or {}).get('first_ionization_energy_eV') for x in sites]
    affinity = [(props.get(x.get('element')) or {}).get('electron_affinity_eV') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    mu = [0.0] * n
    hardness = [0.0] * n
    for i in range(n):
        if ion[i] is not None and affinity[i] is not None and ion[i] > 0 and ion[i] > affinity[i]:
            mu[i] = 0.5 * (ion[i] + affinity[i])
            hardness[i] = ion[i] - affinity[i]
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and hardness[i] > 0 and hardness[j] > 0:
                if d <= 1.3 * (r[i] + r[j]):
                    value += occ[i] * occ[j] * (mu[i] - mu[j]) ** 2 / (hardness[i] + hardness[j])
    total = sum(occ)
    return 0.5 * value / total if total > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    weight = 0.0
    value = 0.0
    squared = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                ratio = d / (r[i] + r[j])
                if ratio <= 1.3:
                    w = occ[i] * occ[j]
                    weight += w
                    value += w * ratio
                    squared += w * ratio * ratio
    if weight <= 0:
        return 0.0
    return sqrt(max(0.0, squared / weight - (value / weight) ** 2))

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    r = [(props.get(x.get('element')) or {}).get('covalent_radius_A') for x in sites]
    chi = [(props.get(x.get('element')) or {}).get('eneg') for x in sites]
    occ = [max(0.0, x.get('occupancy') if x.get('occupancy') is not None else 1.0) for x in sites]
    signed = [0.0] * n
    weights = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and chi[i] is not None and chi[j] is not None:
                if d <= 1.3 * (r[i] + r[j]):
                    w = occ[j] / max(d * d, 0.01)
                    signed[i] += w * (chi[j] - chi[i])
                    weights[i] += w
    value = 0.0
    total = 0.0
    for i in range(n):
        if weights[i] > 0:
            value += occ[i] * (signed[i] / weights[i]) ** 2
            total += occ[i]
    return sqrt(max(0.0, value / total)) if total > 0 else 0.0
